//
// SOURCE-OF-TRUTH STATUS (user-authorised): the 14 source files under
// Purchasing_Team/ were read in full during discovery. The user has
// authorised implementation WITHOUT resolving the conflicts found between
// those sources. Per the authorisation, every disputed item is EXCLUDED from
// learner-facing content rather than resolved by picking, averaging, or
// repairing a value. See docs/purchasing-team-exclusions.md for the full
// register (12 mandatory exclusion categories) and
// docs/purchasing-team-source-map.md for the complete source inventory and
// authority model.
//
// SOURCE AUTHORITY MODEL APPLIED (see programme descriptor + source-map for
// detail): (1) written Purchasing policies/procedures/BGCT operational
// documents are the primary learner-content sources; (2) PO Decision Engine
// written rules/specs are supplemental, used only where internally
// consistent and non-conflicting; (3) Excel workbooks are formula/reference
// sources only, used only where internally correct and consistent with
// written sources; (4) the HTML UI prototype is interface/reference evidence
// only, never policy truth; (5) samples/worked examples are illustrations
// only, never taught as universal policy.
//
// MANDATORY EXCLUSIONS APPLIED THROUGHOUT (never taught, never quizzed):
//  - the disputed container-fill CBM threshold (three different values found
//    across sources) — container-capacity concepts are taught without ever
//    stating a specific CBM number;
//  - the disputed Tier-A warehouse-capacity cutoff (two different values);
//  - the conflicting Gate 2 / Gate 5 / Gate 6 definitions and their disputed
//    activation status;
//  - the True Contribution / margin formula (a labour-inclusive version and
//    a labour-exclusive version conflict) — no version of this formula is
//    taught or used;
//  - the Container_Scoring_Model_V2.2.xlsx off-by-one CBM-subtraction defect
//    and its mislabeled summary rows;
//  - the hardcoded Gate-5 "PASS" stub;
//  - any wording where "MD" cannot be unambiguously distinguished from a
//    generic "management approval" role — a generic role label is used
//    instead, and the ambiguity itself is never presented as resolved;
//  - any sample workbook result presented as if it were universal policy.
// Real supplier names, informally-coded supplier identities, named
// individual staff, internal channel/facility names, and any other
// confidential detail identified during discovery are replaced with generic
// role/entity wording or fictional neutral examples throughout.

const PROGRAMME_ID = 'prog-purchasing-onboarding';

const module = (id, orderIndex, title, summary, estimatedMinutes, source, prerequisiteModuleIds) => ({
  id,
  programmeId: PROGRAMME_ID,
  orderIndex,
  title,
  summary,
  estimatedMinutes,
  prerequisiteModuleIds: prerequisiteModuleIds || [],
  // Purchasing Team requires NO team-leader / reviewer sign-off (confirmed prototype default).
  requiresSignoff: false,
  status: 'FINAL_TRUTH',
  source,
});

const lesson = (id, moduleId, orderIndex, title, content, estimatedMinutes, source) => ({
  id,
  moduleId,
  orderIndex,
  title,
  content,
  estimatedMinutes,
  required: true,
  status: 'FINAL_TRUTH',
  source,
});

